
#!/bin/bash

# Mementic Mainnet Deployment Script
# This script deploys Mementic to the Internet Computer mainnet

set -e

echo "🚀 Starting Mementic Mainnet Deployment..."

# Check if dfx is installed
if ! command -v dfx &> /dev/null; then
    echo "❌ dfx is not installed. Please install it first: https://internetcomputer.org/docs/current/developer-docs/setup/install/"
    exit 1
fi

# Check if user is logged in to dfx
echo "🔐 Checking dfx identity..."
dfx identity whoami

# Confirm deployment
echo "⚠️  This will deploy to the INTERNET COMPUTER MAINNET"
echo "💰 This will cost ICP tokens for canister creation and cycles"
read -p "Are you sure you want to continue? (yes/no): " confirm

if [ "$confirm" != "yes" ]; then
    echo "❌ Deployment cancelled"
    exit 1
fi

# Set network to mainnet
echo "🌐 Setting network to mainnet..."
export DFX_NETWORK=ic

# Copy mainnet environment file
echo "📋 Setting up mainnet environment..."
cp .env.mainnet src/Mementic_frontend/.env

# Build the project
echo "🔨 Building project..."
dfx build

# Deploy canisters
echo "📦 Deploying canisters to mainnet..."
dfx deploy --network ic

# Get canister IDs
echo "🆔 Getting deployed canister IDs..."
BACKEND_ID=$(dfx canister id Mementic_backend --network ic)
FRONTEND_ID=$(dfx canister id Mementic_frontend --network ic)

echo ""
echo "✅ Deployment completed successfully!"
echo ""
